    std::vector<std::vector<uint64_t>> incident(mesh.vertices());for(uint64_t triangle=0;triangle<mesh.triangles();++triangle)for(unsigned c=0;c<3;++c)incident[mesh.faces[3*triangle+c]-1].push_back(triangle);
    for(uint64_t vertex=0;vertex<mesh.vertices();++vertex){if(incident[vertex].empty())throw Failure(PENTA_NUMERIC_ARGUMENT,"Triangle surface contains an isolated unused vertex.");std::map<uint64_t,std::vector<uint64_t>> link;for(const auto triangle:incident[vertex]){work.spend();uint64_t pair[2]{};unsigned at=0;for(unsigned c=0;c<3;++c)if(mesh.faces[3*triangle+c]-1!=vertex)pair[at++]=mesh.faces[3*triangle+c]-1;link[pair[0]].push_back(pair[1]);link[pair[1]].push_back(pair[0]);}unsigned endpoints=0;for(const auto& [node,adjacent]:link){(void)node;if(adjacent.size()==1)++endpoints;else if(adjacent.size()!=2)throw Failure(PENTA_NUMERIC_ARGUMENT,"Nonmanifold vertex link is outside the surface contract.");}if(endpoints!=0&&endpoints!=2)throw Failure(PENTA_NUMERIC_ARGUMENT,"Invalid manifold boundary at a vertex.");std::set<uint64_t> visited;std::vector<uint64_t> stack{link.begin()->first};while(!stack.empty()){const auto node=stack.back();stack.pop_back();if(!visited.insert(node).second)continue;for(const auto adjacent:link.at(node))stack.push_back(adjacent);}if(visited.size()!=link.size())throw Failure(PENTA_NUMERIC_ARGUMENT,"Disconnected vertex link is nonmanifold.");}
